def check_good_function(n, g, a, b):
    if a == b:
        return True
    diff_g = g(a) - g(b)
    diff_a_n_b_n = a**n - b**n

    # Check divisibility: diff_g must divide diff_a_n_b_n
    if diff_g == 0:
        # If difference in g is 0, then a^n - b^n must be 0 too (i.e., a=b, contradiction)
        # Since we know a != b, diff_a_n_b_n != 0 usually.
        # But if g(a)=g(b)=1, and a!=b, then 0 must divide a^n - b^n. This is false unless a^n = b^n.
        # Since a, b are integers, a^n = b^n implies a = -b if n is even, or a=b if n is odd.
        # We assume the problem implies that 0 divides 0, but requires 0 NOT to divide a non-zero number.
        return False # If diff_g = 0 and a != b, then a^n - b^n != 0 (unless n is even and a=-b, which is handled below)

    if diff_a_n_b_n == 0:
        return True # Any non-zero divisor divides 0

    return diff_a_n_b_n % diff_g == 0

# Test n=2, linear functions g(x) = kx + (1-k)
def linear_g(k):
    return lambda x: k * x + (1 - k)

def verify_n2(k):
    g = linear_g(k)
    # Test against several pairs (a, b)
    test_pairs = [(2, 1), (3, 1), (3, 2), (4, 1), (4, 2)]
    for a, b in test_pairs:
        if not check_good_function(2, g, a, b):
            return False
    return True

print("--- Testing n=2 Linear Candidates ---")
possible_k = []
for k in range(-5, 6):
    if verify_n2(k):
        possible_k.append(k)
print(f"Linear solutions found for n=2 (k values): {possible_k}")

